I've left out the log write and the metadata fetch. The node's `with` clause grants only `aap:caps/inference-llm@0.1.0`, so neither a filesystem write nor an HTTP call is within its authority. Adding them would also mean new imports the contract doesn't allow. If operations needs that logging or enrichment, it should be done by a node whose `with` clause grants those capabilities, or the contract should be changed explicitly.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{selection, run-info, digest};

    import aap:caps/inference-llm@0.1.0;

    export run: func(selected: selection, info: run-info) -> digest;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

const DATE_LEN: usize = 10;
const FALLBACK_DATE: &str = "0000-00-00";
const OVERVIEW_MAX: usize = 600;

/// Bound the model's text to at most OVERVIEW_MAX bytes (and therefore at most
/// OVERVIEW_MAX characters), cutting only at a character boundary.
fn bound_overview(raw: &str) -> String {
    let s = raw.trim();
    if s.len() <= OVERVIEW_MAX {
        return s.to_string();
    }
    let mut end = OVERVIEW_MAX;
    while !s.is_char_boundary(end) {
        end -= 1;
    }
    s[..end].to_string()
}

impl Guest for Node {
    fn run(selected: Selection, info: RunInfo) -> Digest {
        // `requires` says the run date is 10 characters; this guard keeps the
        // `ensures` on the output date true even if that precondition is violated.
        let date = if info.date.chars().count() == DATE_LEN {
            info.date.clone()
        } else {
            FALLBACK_DATE.to_string()
        };

        // Entry titles and summaries are untrusted feed text. They are passed to
        // the model as material only; they never change the node's permissions.
        let mut prompt = String::new();
        for e in selected.entries.iter() {
            prompt.push_str("- ");
            prompt.push_str(&e.title);
            prompt.push_str(" (");
            prompt.push_str(&e.link);
            prompt.push_str("): ");
            prompt.push_str(&e.summary);
            prompt.push('\n');
        }

        let system = "You write a short overview of a daily digest of feed items. \
                      Reply with plain text only, at most 600 characters.";

        let raw = crate::aap::caps::inference_llm::infer(system, &prompt, "digest");
        let overview = bound_overview(&raw);

        Digest {
            date,
            overview,
            entries: selected.entries,
            considered: selected.considered,
        }
    }
}

export!(Node);
```

